<template>
  <li
    :id="`${contentId}-${index}`"
    role="option"
    :aria-selected="selected"
    :aria-disabled="disabled || undefined"
    :style="optionStyle"
    :class="[
      ns.be('dropdown', 'item'),
      ns.is('selected', selected),
      ns.is('disabled', disabled),
      ns.is('created', created),
      ns.is('hovering', hovering),
      ns.is('multiple', multiple),
      ns.is('section-start', showSelectionSection),
    ]"
    @mousemove="hoverItem"
    @click.stop="selectOptionClick"
    @mouseenter="handleCellMouseEnter"
  >
    <div
      v-if="showSelectionSection"
      :class="[ns.be('dropdown', 'section-title'), ns.is('unselected-section')]"
      @click.stop
      @mousemove.stop
    >
      Unselected
    </div>
    <div class="option-wrap">
      <el-radio
        v-if="!multiple"
        :model-value="selected"
        :value="true"
        :disabled="disabled"
        @click.stop
        @change="selectOptionClick"
      />
      <el-checkbox
        v-if="multiple"
        :model-value="selected"
        :disabled="disabled"
      />
      <el-tooltip
        ref="tooltipRef"
        effect="light"
        :disabled="
          select.props.showOptionTooltip === false || !isTextOverflowing
        "
        placement="right"
        popper-class="tipPopperClass"
      >
        <template #content>
          <div v-if="isTextOverflowing">{{ getLabel(item) }}</div>
          <div v-if="currentTip">{{ currentTip }}</div>
        </template>
        <div
          class="option-wrap-content"
          :class="{ 'option-wrap-custom-content': hasDefaultSlot }"
        >
          <slot
            v-if="hasDefaultSlot"
            :item="item"
            :index="index"
            :disabled="disabled"
          />
          <template v-else>
            <slot name="optionIcon"></slot>
            <span
              class="select-label"
              :class="{ 'select-margin': $slots?.optionIcon }"
              >{{ getLabel(item) }}</span
            >
          </template>
        </div>
      </el-tooltip>
    </div>
  </li>
</template>

<script lang="ts">
import {
  Comment,
  Fragment,
  Text,
  computed,
  defineComponent,
  inject,
  ref,
} from 'vue'
import {
  getPadding,
  isGreaterThan,
} from '@element-plus/components/table/src/util'
import ElCheckbox from '@element-plus/components/checkbox'
import ElRadio from '@element-plus/components/radio'
import ElTooltip from '@element-plus/components/tooltip'
import { useNamespace } from '@element-plus/hooks'
import { useOption } from './useOption'
import { useProps } from './useProps'
import {
  SELECT_V2_DEFAULT_ITEM_HEIGHT,
  optionV2Emits,
  optionV2Props,
} from './defaults'
import { selectV2InjectionKey } from './token'

import type { VNode } from 'vue'

const hasMeaningfulSlotContent = (content: unknown): boolean => {
  if (Array.isArray(content)) {
    return content.some(hasMeaningfulSlotContent)
  }
  if (typeof content === 'string' || typeof content === 'number') {
    return Boolean(String(content).trim())
  }
  if (!content || typeof content !== 'object') return false

  const node = content as VNode
  if (node.type === Comment) return false
  if (node.type === Text) {
    return Boolean(String(node.children ?? '').trim())
  }
  if (node.type === Fragment) {
    return hasMeaningfulSlotContent(node.children)
  }
  return true
}

export default defineComponent({
  components: { ElCheckbox, ElRadio, ElTooltip },
  props: optionV2Props,
  emits: optionV2Emits,
  setup(props, { emit, slots }) {
    const select = inject(selectV2InjectionKey)!
    const isTextOverflowing = ref(false)
    const ns = useNamespace('select')
    const multiple = computed(() => select.props.multiple)
    const { hoverItem, selectOptionClick } = useOption(props, { emit })
    const { getLabel, getTip } = useProps(select.props)
    const currentTip = computed(() => getTip(props.item))
    const hasDefaultSlot = computed(() =>
      hasMeaningfulSlotContent(
        slots.default?.({
          item: props.item,
          index: props.index,
          disabled: props.disabled,
        }) ?? []
      )
    )
    const contentId = select.contentId
    const optionStyle = computed(() => {
      const virtualStyle = { ...props.style }
      if (virtualStyle.height === `${SELECT_V2_DEFAULT_ITEM_HEIGHT}px`) {
        delete virtualStyle.height
      }

      return virtualStyle
    })
    const handleCellMouseEnter = (event: MouseEvent) => {
      const cellChild = (event.target as HTMLElement).querySelector(
        '.option-wrap-content'
      ) as HTMLElement
      if (!cellChild) return
      if (cellChild && !cellChild?.childNodes.length) {
        isTextOverflowing.value = false
        return
      }

      const range = document.createRange()
      range.setStart(cellChild, 0)
      range.setEnd(cellChild, cellChild.childNodes.length)
      const { width: rangeWidth, height: rangeHeight } =
        range.getBoundingClientRect()
      const { width: cellChildWidth, height: cellChildHeight } =
        cellChild.getBoundingClientRect()

      const { top, left, right, bottom } = getPadding(cellChild)
      const horizontalPadding = left + right
      const verticalPadding = top + bottom
      isTextOverflowing.value =
        isGreaterThan(rangeWidth + horizontalPadding, cellChildWidth) ||
        isGreaterThan(rangeHeight + verticalPadding, cellChildHeight) ||
        isGreaterThan(cellChild.scrollWidth, cellChildWidth)
    }
    return {
      ns,
      select,
      contentId,
      multiple,
      hasDefaultSlot,
      isTextOverflowing,
      currentTip,
      showSelectionSection: computed(() => props.showSelectionSection),
      optionStyle,
      hoverItem,
      selectOptionClick,
      getLabel,
      handleCellMouseEnter,
    }
  },
})
</script>
